// Pseudocode: canonicalize v1/v2 events
function canonicalize(event) {
  const v = event.version || (event.type === 'v2' ? 2 : 1);
  if (v === 1) return mapV1toCanonical(event);
  if (v === 2) return mapV2toCanonical(event);
  throw new Error('Unsupported schema version');
}
